<script setup lang="ts">
import { onMounted, ref } from 'vue'; import AppCard from '../../components/AppCard.vue'; import { commerceRepository } from '../../services/api/repositories'; import type { Order } from '../../types/domain'; import { uniApi as uni } from '../../services/platform/uni'
const orders = ref<Order[]>([]); const activeTab = ref('全部'); const tabs = ['全部', '服务套餐', '加值服务', '单次咨询']; onMounted(async () => { orders.value = await commerceRepository.listOrders() }); const buy = () => uni.navigateTo({ url: '/pages/plans/formal' }); const details = (order: Order) => uni.showModal({ title: order.planName, content: `订单状态：${order.status}\n金额：¥${(order.priceFen / 100).toFixed(2)}\n下单时间：${order.createdAt}`, showCancel: false }); const goService = () => uni.navigateTo({ url: '/pages/service/index' })
</script>
<template><view class="page"><view class="topbar"><text class="back" @click="uni.navigateBack()">‹</text><text class="top-title">我的订单</text><text @click="uni.navigateTo({ url: '/pages/plans/formal' })">♧</text></view><view class="tabs"><text v-for="tab in tabs" :key="tab" :class="{ active: activeTab === tab }" @click="activeTab = tab">{{ tab }}</text></view><AppCard v-if="!orders.length" class="empty"><text class="empty-icon">□</text><text>暂无订单</text><button class="btn" @click="buy">去选择服务</button></AppCard><AppCard v-for="order in orders" :key="order.id" class="order"><view class="order-head"><text class="name">{{ order.planName }}</text><text class="status">{{ order.status }}</text></view><text class="muted">下单时间：{{ order.createdAt }}</text><text class="price">¥{{ (order.priceFen / 100).toFixed(2) }}</text><view class="order-actions"><button class="outline" @click="details(order)">订单详情</button><button class="btn small-btn" @click="goService">去服务</button></view></AppCard></view></template>
<style scoped>.topbar,.tabs,.order-head,.order-actions{display:flex;align-items:center;justify-content:space-between}.topbar{height:82rpx}.back{font-size:48rpx}.top-title{font-size:36rpx;font-weight:700}.tabs{padding:18rpx 0 24rpx;color:#8B8179;font-size:21rpx}.tabs text{padding-bottom:10rpx}.active{color:#d96b2b;font-weight:700;border-bottom:4rpx solid #d96b2b}.empty{text-align:center;padding:70rpx 28rpx}.empty-icon{display:block;font-size:70rpx;color:#b9c9c4}.empty .btn{margin-top:25rpx}.order{padding:24rpx;margin-top:16rpx}.name{font-size:29rpx;font-weight:700}.status{padding:8rpx 14rpx;border-radius:12rpx;color:#f04438;background:#fff0ed;font-size:21rpx}.muted{display:block;margin-top:14rpx;color:#8B8179;font-size:22rpx}.price{display:block;margin-top:16rpx;font-size:34rpx;font-weight:800}.order-actions{justify-content:flex-end;gap:14rpx;margin-top:18rpx}.outline{height:68rpx;line-height:68rpx;padding:0 22rpx;border:1rpx solid #dceae6;border-radius:16rpx;background:#fff;color:#58706b}.small-btn{width:150rpx;height:68rpx;line-height:68rpx}</style>

